"""Context builder: assembles a bounded, token-aware system/user prompt."""

import logging
from dataclasses import dataclass
from typing import Optional

from ..ai.base import ChatMessage
from ..memory.service import MemoryService
from ..conversation.personality import Personality

logger = logging.getLogger("rosy.context")

# Rough token estimate for display/limiting purposes.
_CHARS_PER_TOKEN = 4


@dataclass
class ContextBundle:
    system: str
    user_messages: list[ChatMessage]


class ContextBuilder:
    """Builds a context bundle for a single response."""

    def __init__(self, personality: Personality, max_tokens: int = 4000):
        self.personality = personality
        self.max_tokens = max_tokens

    @staticmethod
    def _est_tokens(text: str) -> int:
        return max(1, len(text) // _CHARS_PER_TOKEN)

    def build(
        self,
        *,
        message_text: str,
        author_name: str,
        memories: list,
        recent_history: list[ChatMessage] | None = None,
        guild_name: Optional[str] = None,
        extra_system: str = "",
    ) -> ContextBundle:
        parts = [self.personality.system_prompt]

        if guild_name:
            parts.append(f"Context: you are chatting in the server \"{guild_name}\".")

        memory_lines = [
            f"- [{m.memory_type}] {m.key}: {m.value}" for m in memories[:8]
        ]
        if memory_lines:
            parts.append("What you remember (use it naturally, do not quote it verbatim):\n" + "\n".join(memory_lines))

        if extra_system:
            parts.append(extra_system)

        system = "\n\n".join(parts)

        user_messages: list[ChatMessage] = []
        budget = self.max_tokens - self._est_tokens(system) - self._est_tokens(message_text)

        # Build recent history, newest-last, trimming from the front to stay in budget.
        if recent_history:
            history: list[ChatMessage] = list(recent_history)
            while history and self._est_tokens(sum(m.content for m in history)) > budget:
                history.pop(0)
            user_messages.extend(history)

        user_messages.append(
            ChatMessage(role="user", content=f"{author_name}: {message_text}")
        )
        return ContextBundle(system=system, user_messages=user_messages)

"""Base classes and dataclasses for tools."""

import logging
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any

logger = logging.getLogger("rosy.tools")


@dataclass
class ToolSpec:
    name: str
    description: str
    parameters: dict = field(default_factory=dict)


class Tool(ABC):
    """A single capability Rosy can invoke. Override :meth:`execute`."""

    name: str = "base"
    description: str = ""
    permission: str = "member"  # member | admin
    timeout: float = 15.0

    def __init__(self) -> None:
        self.log = logging.getLogger(f"rosy.tool.{self.name}")

    def schema(self) -> dict:
        return {
            "type": "function",
            "function": {
                "name": self.name,
                "description": self.description,
                "parameters": self.parameters,
            },
        }

    @abstractmethod
    async def execute(self, **kwargs: Any) -> str:
        raise NotImplementedError

    async def safe_execute(self, **kwargs: Any) -> str:
        try:
            self.log.debug("Executing %s", self.name)
            return await self.execute(**kwargs)
        except Exception as exc:  # noqa: BLE001
            self.log.exception("Tool %s failed", self.name)
            return f"[tool {self.name} error: {type(exc).__name__}]"

"""Tool registry and permission gating."""

from typing import Optional

from .base import Tool
from .math_tool import CalculateTool
from .web import WebSearchTool


class ToolRegistry:
    """Holds all available tools and applies per-guild enablement."""

    def __init__(self) -> None:
        self._tools: dict[str, Tool] = {}

    def register(self, tool: Tool) -> None:
        self._tools[tool.name] = tool

    def register_defaults(self) -> None:
        self.register(CalculateTool())
        self.register(WebSearchTool())

    def get(self, name: str) -> Optional[Tool]:
        return self._tools.get(name)

    def all(self) -> list[Tool]:
        return list(self._tools.values())

    def schemas(self, *, is_admin: bool = False, enabled: set[str] | None = None) -> list[dict]:
        out = []
        for tool in self._tools.values():
            if enabled is not None and tool.name not in enabled:
                continue
            if tool.permission == "admin" and not is_admin:
                continue
            out.append(tool.schema())
        return out

    async def invoke(self, name: str, *, is_admin: bool = False, **kwargs) -> str:
        tool = self._tools.get(name)
        if tool is None:
            return f"[unknown tool: {name}]"
        if tool.permission == "admin" and not is_admin:
            return "[permission denied: this tool requires admin]"
        return await tool.safe_execute(**kwargs)

"""Deterministic calculation tool.

We prefer deterministic evaluation over asking an LLM to guess arithmetic. The
expression parser is a tiny, safe subset — no imports, no attribute access.
"""

import ast
import operator

from .base import Tool

_ALLOWED_NODES = (
    ast.Expression,
    ast.Constant,
    ast.BinOp,
    ast.UnaryOp,
    ast.Name,
    ast.Load,
    ast.Pow,
    ast.Add,
    ast.Sub,
    ast.Mult,
    ast.Div,
    ast.FloorDiv,
    ast.Mod,
    ast.USub,
    ast.UAdd,
)

_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY = {ast.USub: operator.neg, ast.UAdd: operator.pos}


class _SafeEval(ast.NodeVisitor):
    def visit_Constant(self, node: ast.Constant) -> float:
        if not isinstance(node.value, (int, float)):
            raise ValueError("Only numeric constants are allowed.")
        return float(node.value)

    def visit_Name(self, node: ast.Name) -> float:
        raise ValueError(f"Variables are not allowed ({node.id}).")

    def visit_BinOp(self, node: ast.BinOp) -> float:
        if type(node.op) not in _BINOPS:
            raise ValueError("Unsupported operator.")
        return _BINOPS[type(node.op)](self.visit(node.left), self.visit(node.right))

    def visit_UnaryOp(self, node: ast.UnaryOp) -> float:
        if type(node.op) not in _UNARY:
            raise ValueError("Unsupported unary operator.")
        return _UNARY[type(node.op)](self.visit(node.operand))

    def visit_Expression(self, node: ast.Expression) -> float:
        return self.visit(node.body)


class CalculateTool(Tool):
    name = "calculate"
    description = "Evaluate a safe arithmetic expression and return the result."
    parameters = {
        "type": "object",
        "properties": {"expression": {"type": "string", "description": "Math expression, e.g. (2 + 3) * 4"}},
        "required": ["expression"],
    }

    async def execute(self, expression: str = "") -> str:
        if not expression:
            return "Provide an expression."
        try:
            tree = ast.parse(expression, mode="eval")
            for node in ast.walk(tree):
                if not isinstance(node, _ALLOWED_NODES):
                    raise ValueError("Expression contains unsupported constructs.")
            result = _SafeEval().visit(tree)
            return f"{expression} = {result}"
        except (ValueError, SyntaxError, ZeroDivisionError) as exc:
            return f"Error evaluating expression: {exc}"

